145:     /**
146:      *  Class for managing intervals.
147:      *  Auto-delaying/boosting depending on server lag.
148:      *  Faking intervals by timeouts.
149:      *
150:      * @param {type} fn
151:      * @param {type} delay
152:      * @param {bool} blocking If true, the fn is an AJAX call. The fn will not be called again unless it calls `this.blocking = false` when AJAX is finished.
153:      *      You may wont to include `.always(() => {this.blocking = false;})` after the AJAX call. (In 'this' should be instance of the Interval object.)
154:      *
155:      *      (Note that we preferred that.blocking setter over method unblock() because interval function
156:      *      can be called from other sources than this class (ex: at first run) and a non-existent method would pose a problem.)
157:      * @returns {Interval}
158:      */
159:     constructor(fn, delay, ajax_wait) {
160:         this.fn = fn;
161:         this.delay = this._delay = delay;
162:         this._delayed = function () {
163:             this.time1 = +new Date();
164:             this.fn.call(this);
165:             if (ajax_wait !== true && this.running) {
166:                 this.start();
167:             }
168:         }.bind(this);
169:         this.start();
170:     }
171:     start() {
172:         this.running = true;
173:         this.instance = setTimeout(this._delayed, this._delay);
174:         return this;
175:     }
176:     stop() {
177:         setTimeout(this.instance);
178:         this.running = false;
179:         return this;
180: 
181:     }
