124: function ajax_fail_callback(str) {
125:     return function (jqXHR, textStatus, message) {
126:         if (textStatus === "timeout") {
127:             // this is just a timeout, no other info needed
128:             show_error(str + " timeout");
129:             return;
130:         }
131:         if (jqXHR.status === 0) { // page refreshed before ajax finished
132:             return;
133:         }
134:         // include full report but truncate the length to 200 chars
135:         // (since '.' is not matching newline characters, we're using '[\s\S]' so that even multiline string is shortened)
136:         show_error("{0}: <b>{1}</b> {2}".format(str, jqXHR.responseText.replace(/^(.{200})[\s\S]+/, "$1..."), message));
137:     };
138: }
